using System;
using System.Collections.Generic;
namespace ElswordPixel.CargoPresentationV21 {
 [Serializable] public sealed class NpcAttachmentPoint {public float x,y,z;}
 [Serializable] public sealed class CargoCallbackBindingV21 {public string id,npc,state,sourceCallback,sourceInstructionsSha256,particleKey,phase;public int sourceLiteralPC;}
 [Serializable] public sealed class CargoFxOwnerV21 {public int serial;public string npc;public float nativeDepth;}
 [Serializable] public sealed class CargoLiveEffectV21 {
  public int serial,facing=1;public string id;public float x,y,z,age,lifetime,angle,scaleX=1,scaleY=1,scaleZ=1,ownerScale=1,sourceLandY;public bool hasSourceLandY;public CargoFxOwnerV21 owner;
 }
 [Serializable] public sealed class CargoEffectEventV21 {public int sequence,serial,facing=1;public string effect,type,npc;public float time,x,y,z,depth,scale=1,landY;public bool hasSourceLandY;}
 [Serializable] public sealed class CargoObservedParticleV21 {
  public int sequence,handle,ownerSerial,facing=1;public string kind,bindingId,npc,state,sourceInstructionsSha256,particleKey;public float time,sourceLocalTime,x,y,z,depth,landY,unit=.28f;public bool continuous,hasSourceLandY;
 }
 // Snapshot feed only. The Host commits model-owned movement/damage results;
 // this presentation layer never advances a GameModel or manufactures hits.
 public sealed class CargoFxFeedV21 {
  public const string ExactEffectsSha256="326a4987918b5a82269d9b640a6973c181b1ce6c74c55fd4fc5159cf900ee2c0";
  internal readonly List<CargoLiveEffectV21> npcEffects=new List<CargoLiveEffectV21>();internal readonly List<CargoEffectEventV21> npcPresentationEvents=new List<CargoEffectEventV21>();internal readonly List<CargoObservedParticleV21> particleRequests=new List<CargoObservedParticleV21>();internal float elapsed;internal int room,NpcPresentationGeneration;internal int LastParticleSequence;
  readonly Dictionary<int,CargoObservedParticleV21> handles=new Dictionary<int,CargoObservedParticleV21>();int effectSequence;readonly Dictionary<string,CargoCallbackBindingV21> bindings=new Dictionary<string,CargoCallbackBindingV21>();
  public CargoFxFeedV21(string sourceEffectsSha256,CargoCallbackBindingV21[] sourceBindings){if(sourceEffectsSha256!=ExactEffectsSha256||sourceBindings==null)throw new ArgumentException("Wrong exact Cargo effects/bindings");foreach(var b in sourceBindings){if(b==null||string.IsNullOrEmpty(b.id)||string.IsNullOrEmpty(b.sourceInstructionsSha256)||b.sourceInstructionsSha256.Length!=64||bindings.ContainsKey(b.id))throw new ArgumentException("Invalid callback source identity");bindings.Add(b.id,b);}}
  public static bool Finite(float v){return !float.IsNaN(v)&&!float.IsInfinity(v);}
  public static string OwnerForEffect(string id){if(id=="DamageEffect_BEE_NASOD_ATTACK_A")return"NUI_BEE_NASOD";if(id=="DamageEffect_NASOD_MINER_FAT_B_ATTACK_A")return"NUI_NASOD_MINER_FAT_B_AIR";if(id=="DamageEffect_NASOD_MINER_FAT_C_ATTACK_A"||id=="DamageEffect_NASOD_MINER_FAT_C_ATTACK_A2"||id=="DamageEffect_NASOD_MINER_FAT_C_ATTACK_B")return"NUI_NASOD_MINER_FAT_C_AIR";if(id=="DamageEffect_WALLY_9TH_ARMOR_ATTACK_A"||id=="DamageEffect_WALLY_9TH_ARMOR_ATTACK_B"||id=="DamageEffect_WALLY_9TH_ARMOR_ATTACK_C"||id=="DamageEffect_WALLY_9TH_ARMOR_ATTACK_C_EXPLOSION"||id=="DamageEffect_WALLY_9TH_ARMOR_SPECIAL_ATTACK_A")return"NUI_WALLY_9TH_ARMOR";return null;}
  public static void ValidateLive(CargoLiveEffectV21 e){if(e==null||e.serial<=0||e.owner==null||e.owner.serial<=0||OwnerForEffect(e.id)!=e.owner.npc||e.facing!=1&&e.facing!=-1||!Finite(e.x)||!Finite(e.y)||!Finite(e.z)||!Finite(e.angle)||!Finite(e.age)||e.age<0||!Finite(e.lifetime)||e.lifetime<=0||e.age>=e.lifetime||!Finite(e.ownerScale)||e.ownerScale<=0||!Finite(e.scaleX)||!Finite(e.scaleY)||!Finite(e.scaleZ)||e.scaleX<0||e.scaleY<0||e.scaleZ<0||e.hasSourceLandY&&!Finite(e.sourceLandY))throw new ArgumentException("Invalid committed exact Cargo effect snapshot");}
  static CargoObservedParticleV21 Copy(CargoObservedParticleV21 e){return new CargoObservedParticleV21{sequence=e.sequence,handle=e.handle,ownerSerial=e.ownerSerial,facing=e.facing,kind=e.kind,bindingId=e.bindingId,npc=e.npc,state=e.state,sourceInstructionsSha256=e.sourceInstructionsSha256,particleKey=e.particleKey,time=e.time,sourceLocalTime=e.sourceLocalTime,x=e.x,y=e.y,z=e.z,depth=e.depth,landY=e.landY,unit=e.unit,continuous=e.continuous,hasSourceLandY=e.hasSourceLandY};}
  static CargoEffectEventV21 Copy(CargoEffectEventV21 e){return new CargoEffectEventV21{sequence=e.sequence,serial=e.serial,facing=e.facing,effect=e.effect,type=e.type,npc=e.npc,time=e.time,x=e.x,y=e.y,z=e.z,depth=e.depth,scale=e.scale,landY=e.landY,hasSourceLandY=e.hasSourceLandY};}
  static CargoLiveEffectV21 Copy(CargoLiveEffectV21 e){return new CargoLiveEffectV21{serial=e.serial,facing=e.facing,id=e.id,x=e.x,y=e.y,z=e.z,age=e.age,lifetime=e.lifetime,angle=e.angle,scaleX=e.scaleX,scaleY=e.scaleY,scaleZ=e.scaleZ,ownerScale=e.ownerScale,sourceLandY=e.sourceLandY,hasSourceLandY=e.hasSourceLandY,owner=new CargoFxOwnerV21{serial=e.owner.serial,npc=e.owner.npc,nativeDepth=e.owner.nativeDepth}};}
  public void ResetRoom(int generation,int roomId){NpcPresentationGeneration=generation;room=roomId;elapsed=0;npcEffects.Clear();npcPresentationEvents.Clear();particleRequests.Clear();handles.Clear();effectSequence=LastParticleSequence=0;}
  public void SetFrame(float at,CargoLiveEffectV21[] effects){if(!Finite(at)||at<0||at<elapsed||effects==null)throw new ArgumentException("Rewind requires explicit ResetRoom");var seen=new HashSet<int>();foreach(var e in effects){ValidateLive(e);if(!seen.Add(e.serial))throw new ArgumentException("Duplicate effect serial");}elapsed=at;npcEffects.Clear();foreach(var e in effects)npcEffects.Add(Copy(e));}
  public void SubmitEffectEvent(CargoEffectEventV21 e){if(e==null||e.sequence<=effectSequence||e.serial<=0||e.type!="spawn"&&e.type!="hit"||OwnerForEffect(e.effect)!=e.npc||!Finite(e.time)||e.time<0||e.time>elapsed+.0001f||!Finite(e.x)||!Finite(e.y)||!Finite(e.z)||!Finite(e.depth)||!Finite(e.scale)||e.scale<=0||e.facing!=1&&e.facing!=-1||e.hasSourceLandY&&!Finite(e.landY))throw new ArgumentException("Invalid Cargo committed spawn/hit event");effectSequence=e.sequence;npcPresentationEvents.Add(Copy(e));}
  public void SubmitObservedParticle(CargoObservedParticleV21 e){CargoCallbackBindingV21 b;if(e==null||e.sequence<=LastParticleSequence||!bindings.TryGetValue(e.bindingId??"",out b)||b.npc!=e.npc||b.state!=e.state||b.sourceInstructionsSha256!=e.sourceInstructionsSha256||b.particleKey!=e.particleKey||e.ownerSerial<=0||!Finite(e.time)||e.time<0||e.time>elapsed+.0001f||!Finite(e.sourceLocalTime)||e.sourceLocalTime<0||!Finite(e.x)||!Finite(e.y)||!Finite(e.z)||!Finite(e.depth)||!Finite(e.unit)||e.unit<=0||e.hasSourceLandY&&!Finite(e.landY)||e.facing!=1&&e.facing!=-1)throw new ArgumentException("Unbound observed Cargo callback request");if(e.kind=="spawn"){if(e.continuous&&e.handle<=0||e.handle>0&&handles.ContainsKey(e.handle))throw new ArgumentException("Ambiguous particle owner handle");if(e.handle>0)handles.Add(e.handle,Copy(e));}else{CargoObservedParticleV21 start;if(e.kind!="move"&&e.kind!="stop"&&e.kind!="destroy"||!handles.TryGetValue(e.handle,out start)||start.ownerSerial!=e.ownerSerial||start.bindingId!=e.bindingId)throw new ArgumentException("Wrong particle lifecycle owner");if(e.kind!="move")handles.Remove(e.handle);}LastParticleSequence=e.sequence;particleRequests.Add(Copy(e));}
  internal CargoLiveEffectV21 NpcEffectVisual(CargoLiveEffectV21 e){return e;}
 }
}
